// WorldItemSnapshotSynchronizer.ApplyFishes — 게스트에서 RoomClient.OnSnapshot이 부름 (발췌)
private void ApplyFishes(FishState[] fishStates)
{
// (Why) "이번 스냅샷에 없는 것 = 호스트에서 사라진 것"으로 판단하려고,
//       등록된 물고기 번호 전체에서 시작해 받은 것을 하나씩 지운다.
HashSet<int> missingFishWorldItemIds = new HashSet<int>(worldItemRegistry.WorldItems.Keys);
missingFishWorldItemIds.ExceptWith(worldItemRegistry.FixedWorldItemIds);

foreach (FishState state in fishStates)
{
if (worldItemRegistry.TryGetWorldItem(state.WorldItemId, out WorldItem worldItem) == false)
{
// (Why) 처음 보는 번호 → 풀에서 꺼내 호스트와 같은 번호로 등록
worldItem = FishObjectPool.Instance.Get(state.ItemId);
if (worldItem == null)
continue;

if (worldItemRegistry.RegisterDynamic(worldItem, state.WorldItemId) == false)
{
FishObjectPool.Instance.Release(worldItem);   // 번호 충돌 → 되돌림
continue;
}
}

if (worldItem.TryGetComponent(out Fish fish) == false)
continue;   // (원본은 에러 로그) 물고기 번호인데 Fish가 아님
// (중략) 같은 번호인데 종류(ItemId)가 다르면 에러 로그 후 건너뜀

bool wasActive = worldItem.gameObject.activeSelf;
worldItem.SetIsPickUp(false);
worldItem.gameObject.SetActive(true);
LockFishForGuest(fish);                          // 게스트는 물고기 이동 로직을 멈춘다
fish.ApplySnapshot(state, wasActive == false);   // 새로 켜진 것은 보간 없이 바로 그 자리에
missingFishWorldItemIds.Remove(state.WorldItemId);
}

foreach (int worldItemId in missingFishWorldItemIds)
{
if (worldItemRegistry.UnregisterDynamic(worldItemId, out WorldItem worldItem))
{
FishObjectPool.Instance.Release(worldItem);
}
}
}

public void BridgeBuild() // 호스트에서만 불림 (Bridge.OnCollisionStay2D)
{
if (IsEnd) return;

int nextBridgeIndex = currentBridgeCount + 1;
if (bridgeTable.TryGet(nextBridgeIndex, out BridgeRef bridgeRef) == false)
return;

// (Why) 먼저 '무엇을 몇 개 쓸지' 계획을 세우고, 계획이 서야만 소비한다 → 재료가 반만 빠지는 일 없음
if (BridgeBuildCostCalculator.TryCreateConsumePlan(
bridgeRef, inventoryItemDB.EnumerateCounts(), itemManager.Items,
out IReadOnlyDictionary<int, int> consumePlan) == false ||
inventoryItemDB.TryConsumeAll(consumePlan) == false)
{
return;
}

StartCoroutine(BuildParticle(currentBridgeCount)); // 연출 후 다리 오브젝트 활성화
// (Why) 개수는 연출과 상관없이 즉시 올린다. 예전엔 켜진 다리 수를 세서 연출 시간만큼 늦게 올랐다 (6.2-4)
currentBridgeCount++;
OnBridgeBuild?.Invoke();
}

// RoomClient — 같은 메시지를 IsHost로 갈라 처리 (발췌)
private void OnGuestInputGroup(GuestInputGroupMessage message)
{
if (Me.IsHost == false) return;            // 게스트 입력은 호스트만 씀
foreach (GuestInputMessage input in message.Inputs)
{
if (remotes.TryGetValue(input.Id, out PlayerController remote) == false) continue;
remote.ApplyInput(new Vector2(input.X, input.Y),          // ② 호스트 안의 게스트
input.IsLeftShiftHold, input.IsRightShiftHold, input.IsBuildKeyHold, ...);
}
}

private void OnSnapshot(SnapshotMessage message)
{
if (Me.IsHost) { SnapshotMessage = message; return; }       // 호스트는 반영 안 함
foreach (PlayerState state in message.Players)
if (remotes.TryGetValue(state.Id, out PlayerController remote))
remote.ApplySnapshot(state, state.IsLeftGrab, state.IsRightGrab);  // ③ 게스트
BridgeManager.Instance.ApplySnapshot(message.CurrentBridgeCount);
// … 물고기·나무, 승패, 인벤토리, 낮/밤
}
